$inputs=@(@($sources)+@(Get-ChildItem -LiteralPath $src -Filter '*.h' -File|ForEach-Object {$_.FullName})+@($PSCommandPath)|ForEach-Object {E $_})
$global:LASTEXITCODE=$null;$lines=& $env:ComSpec /d /c 'call "D:\Program Files\VS2022\Common7\Tools\VsDevCmd.bat" -arch=x64 -host_arch=x64 >nul && set';$envCode=$LASTEXITCODE;if($envCode-isnot[int]-or$envCode-ne0){throw 'VS environment failed'};foreach($line in $lines){$i=$line.IndexOf('=');if($i-gt0){[Environment]::SetEnvironmentVariable($line.Substring(0,$i),$line.Substring($i+1),'Process')}}
